<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Theme Toggle</title>
  <script>
    // Apply the stored theme before first paint to avoid a flash.
    (function () {
      try {
        var t = localStorage.getItem('theme');
        if (t === 'light' || t === 'dark') {
          document.documentElement.setAttribute('data-theme', t);
        }
        // 'system' (or anything else): no attribute -> falls back to OS preference via CSS.
      } catch (e) { /* storage unavailable */ }
    })();
  </script>
  <style>
    :root { color-scheme: light; }
    :root[data-theme='dark'] { color-scheme: dark; }
    @media (prefers-color-scheme: dark) {
      :root:not([data-theme]) { color-scheme: dark; }
    }
    body { font-family: system-ui, sans-serif; margin: 2rem; }
    fieldset { border: 1px solid #888; max-width: max-content; }
    label { display: block; padding: 0.25rem 0; }
  </style>
</head>
<body>
  <h1>Theme</h1>
  <fieldset>
    <legend>Color scheme</legend>
    <label><input type="radio" name="theme" value="light"> Light</label>
    <label><input type="radio" name="theme" value="dark"> Dark</label>
    <label><input type="radio" name="theme" value="system"> System</label>
  </fieldset>

  <script>
    var radios = document.querySelectorAll('input[name="theme"]');

    function apply(value, persist) {
      if (value === 'light' || value === 'dark') {
        document.documentElement.setAttribute('data-theme', value);
      } else {
        // system: remove any explicit choice, defer to OS preference
        document.documentElement.removeAttribute('data-theme');
      }
      if (persist) localStorage.setItem('theme', value);
      syncChecked();
    }

    function syncChecked() {
      var stored = null;
      try { stored = localStorage.getItem('theme'); } catch (e) {}
      var current = stored || 'system';
      radios.forEach(function (r) { r.checked = r.value === current; });
    }

    radios.forEach(function (r) {
      r.addEventListener('change', function () {
        if (r.checked) apply(r.value, true);
      });
    });

    syncChecked();
  </script>
</body>
</html>
"})
