result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/pw-theme/tests/theme.spec.js", "content": "// @ts-check
const { test, expect } = require('@playwright/test');

test.describe('three-way theme toggle persistence', () => {
  test('picking dark persists through reload with data-theme set before paint', async ({ page }) => {
    await page.goto('/');
    await page.check('input[name="theme"][value="dark"]');
    await expect(page.locator('html')).toHaveAttribute('data-theme', 'dark');

    await page.reload();

    // Read the attribute immediately on the fresh load — the inline head script
    // must have applied it before first paint (no post-load JS involved).
    const theme = await page.evaluate(() => document.documentElement.getAttribute('data-theme'));
    expect(theme).toBe('dark');
    await expect(page.locator('input[name="theme"][value="dark"]')).toBeChecked();
  });

  test('switching to system removes the attribute and it stays absent after reload', async ({ page }) => {
    await page.goto('/');
    await page.check('input[name="theme"][value="system"]');
    await expect(page.locator('html')).not.toHaveAttribute('data-theme');

    await page.reload();

    const theme = await page.evaluate(() => document.documentElement.getAttribute('data-theme'));
    expect(theme).toBeNull();
    await expect(page.locator('input[name="theme"][value="system"]')).toBeChecked();
  });

  test('localStorage reflects the explicit choice and the system choice', async ({ page }) => {
    await page.goto('/');
    await page.check('input[name="theme"][value="dark"]');
    let stored = await page.evaluate(() => localStorage.getItem('theme'));
    expect(stored).toBe('dark');

    await page.check('input[name="theme"][value="system"]');
    stored = await page.evaluate(() => localStorage.getItem('theme'));
    expect(stored).toBe('system');
  });
});
"})
